#define main probe_main
#include "diagnose_factor_write4.cpp"
#undef main
#include <fstream>
struct Event{int object,owner;};
int main(int argc,char**argv){try{double threshold=argc>1?std::stod(argv[1]):0;printf("threshold=%.3f\n",threshold);for(unsigned seed:{42u,123u,2026u,7u,999u}){Net net(seed);std::ifstream f("build/factor_write4_"+std::to_string(seed)+".weights",std::ios::binary);if(!f.read((char*)net.w.data(),sizeof(net.w)))throw std::runtime_error("weights");for(int syntax=0;syntax<3;++syntax){std::mt19937 rng(731199+syntax);int wrong=0,miss=0,content=0,polluted=0,parity=0;for(int sample=0;sample<512;++sample){int q=rng()%4,target=q+4*(rng()%2);std::vector<Event>events;events.push_back({q,(q+1)%4});for(int j=0;j<8;++j){int object=(q+1+int(rng()%3))%4;int owner=int(rng()%8);while(owner%4==object)owner=int(rng()%8);events.push_back({object,owner});}events.push_back({q,target});for(int j=0;j<8;++j){int object=(q+1+int(rng()%3))%4;int owner=int(rng()%8);while(owner%4==object)owner=int(rng()%8);events.push_back({object,owner});}Seq s{q,target,{}};std::vector<int>boundary;for(auto e:events){bool reverse=syntax==1||(syntax==0&&rng()%2);if(syntax==2)s.tokens.insert(s.tokens.end(),{e.object,12,4+e.owner,12});else if(reverse)s.tokens.insert(s.tokens.end(),{4+e.owner,e.object,12});else s.tokens.insert(s.tokens.end(),{e.object,4+e.owner,12});boundary.push_back(int(s.tokens.size()));}int memory=0,atRelevant=0,writesRelevant=0;for(int t=0;t<int(s.tokens.size());++t){double h[16],z[9];int ix[6]={q,4+s.tokens[t],17+(t?s.tokens[t-1]:12),30+(t>1?s.tokens[t-2]:12),43+(t>2?s.tokens[t-3]:12),56};for(int j=0;j<16;++j){double a=0;for(int i:ix)if(j<8||i>=4)a+=net.w[j*57+i];h[j]=std::tanh(a);}for(int o=0;o<9;++o){z[o]=net.w[912+o*17+16];for(int j=o?8:0;j<(o?16:8);++j)z[o]+=net.w[912+o*17+j]*h[j];}if(z[0]>=threshold){memory=int(std::max_element(z+1,z+9)-z-1);if(t>=boundary[8]&&t<boundary[9])++writesRelevant;}if(t+1==boundary[9])atRelevant=memory;}int reference;net.run(s,nullptr,nullptr,&reference);if(threshold==0&&reference!=memory)throw std::runtime_error("trace parity");parity+=reference==memory;if(memory!=target){++wrong;if(atRelevant==target)++polluted;else if(writesRelevant==0)++miss;else ++content;}}printf("seed=%u syntax=%d n512 errors=%d no_write_at_last_event=%d wrote_but_wrong_at_last_event=%d correct_then_polluted=%d parity=%d\n",seed,syntax,wrong,miss,content,polluted,parity);}}return 0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 1;}}
